\subsection{Instances, KKT Residual, and Algorithm Family}
\label{subsec:lb-setup}

\begin{definition}[Instance class]
\label{def:instance-class}
Suppose that \(\Delta>0\) and \(\mathbf C=(L_f,G_f,L_{\calA},G_{\calA},L_h)\ge\zero\).
We define \(\mathcal I(\mathbf C,\Delta)\) as the union, over dimensions
\(n,m\in\NN\), of the instances \(I=(f,\calA,h,\bw^0)\) with
\(\bw^0=(\bx^0,\bz^0,\blmbd^0,\bmu^0)\) satisfying the following properties:
\begin{enumerate}[label=(\roman*)]
\item (Smooth part) \(f:\RR^n\to\RR\) is continuously differentiable and,
  for all \(\bx,\bx'\in\RR^n\),
  \[
  \|\nabla f(\bx)-\nabla f(\bx')\|\le L_f\|\bx-\bx'\|,\qquad
  \|\nabla f(\bx)\|\le G_f.
  \]
\item (Inner mapping) \(\calA:\RR^n\to\RR^m\) is continuously differentiable and,
  for all \(\bx,\bx'\in\RR^n\),
  \[
  \|J_{\calA}(\bx)-J_{\calA}(\bx')\|\le L_{\calA}\|\bx-\bx'\|,\qquad
  \|J_{\calA}(\bx)\|\le G_{\calA}.
  \]
\item (Outer function) \(h:\RR^m\to\RR\) is proper, closed, convex, and
  \(\|\bxi\|\le L_h\) for all \(\by\in\RR^m\) and \(\bxi\in\partial h(\by)\).
\item (Initial gap) With \(F=f+h\circ\calA\),
  \[
  F(\bx^0)-\inf_{\bx\in\RR^n}F(\bx)\le\Delta.
  \]
\item (Bounded initialization)
  \(\|\bx^0\|+\|\bz^0\|+\|\blmbd^0\|+\|\bmu^0\|\le1\).
\end{enumerate}
\end{definition}

Since $F(\bx^0)$ is finite, condition~(iv) implies
$\inf_{\bx\in\RR^n}F(\bx)\ge F(\bx^0)-\Delta>-\infty$.

\begin{remark}
\label{rem:instance-initialization}
We first allow the initialization to be selected as part of the instance,
after the algorithmic parameters; see also
\cite[Lemma~5.4]{li2026smoothing} for an instance-dependent initialization.
A fixed rule such as
\(\bz^0=\bx^0\) and \(\blmbd^0=\bmu^0=\zero\) requires a separate
lower-bound argument.
% TODO: Section ? treats the fixed rule; add this statement and its reference
% only after that argument has been proved.
\end{remark}

We next introduce the stationarity measure used in the lower bound.

\begin{definition}[KKT residual]
\label{def:kkt-residual}
Given an instance \(I\) and the iterates of Algorithm~\ref{alg:splalm},
the KKT residual of the triple \((\bx^{k+1},\by^{k+1},\bq^k)\) generated at
iteration \(k\ge0\) is
\[
R_k:=\max\Bigl\{\bigl\|\nabla f(\bx^{k+1})+J_{\calA}(\bx^{k+1})^\top\bq^k\bigr\|,\;
\bigl\|\calA(\bx^{k+1})-\by^{k+1}\bigr\|\Bigr\},
\]
where \(\by^{k+1}:=\by(\bx^{k+1},\blmbd^k)\) and
\(\bq^k:=\blmbd^k+\rho\bigl(\calA(\bx^{k+1})-\by^{k+1}\bigr)\).
\end{definition}

By \eqref{eq:q-subgradient}, \(\bq^k\in\partial h(\by^{k+1})\); hence
\(R_k\le\epsilon\) implies that \((\bx^{k+1},\by^{k+1},\bq^k)\) is an
\(\epsilon\)-KKT point in the sense of Definition~\ref{def:eps-kkt}.
We measure complexity by the first iteration at which this occurs.

